/// 🏷️ Preserves external literal references or resolves the caller's real named partition.
fn doc_reference<'a>(native:Option<&'a str>,names:Option<&[(&str,i64)]>,out:&mut RowWriter<'_,'_>)->Result<Cell<'a>,ValueError>{
