fn brep_sequence<T>(target:&mut Vec<T>,rows:&mut RowIndex<'_>,order:&[usize],id:i64,c:&mut SqliteSnapshotControl<'_>,decode:impl Fn(SqliteRow<'_>)->Result<T,ValueError>)->Result<(),ValueError>{
