}
/// 🛡️ Retains source-index-aligned typed geometry inside its actual retirement owner.
struct BrepGeometry<'a,T:semio_framework_value::retirement::RetireOwned>{rows:RowIndex<'a>,values:Owned<Vec<Option<T>>>}
