 /// 🫴️ Transfers one exact owned geometry identity once.
 fn take(&mut self,id:i64,c:&mut SqliteSnapshotControl<'_>,message:&str)->Result<T,ValueError>{let index=self.rows.position(id,c)?.ok_or_else(||brep_invalid(message))?;self.rows.take_index(index,c)?.ok_or_else(||brep_invalid(message))?;self.values.get_mut()[index].take().ok_or_else(||brep_invalid(message))}
 /// 📦️ Reports the declared geometry not consumed by topology.
 fn remaining(&self)->usize{self.rows.remaining()}
}
/// 📋️ Pays and initializes typed geometry slots before constructing any owned NURBS field.
fn geometry_slots<T:semio_framework_value::retirement::RetireOwned>(count:usize,c:&mut SqliteSnapshotControl<'_>)->Result<Owned<Vec<Option<T>>>,ValueError>{let mut values=Owned::new(transfer::reserve(count,c)?);for index in 0..count{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,index,count)?;values.get_mut().push(None);}Ok(values)}
